//! Ship and module base stats from `data/catalog/ships.json` (generated by `scripts/gen-ships.py`
//! from EDCD/coriolis-data and EDCD/FDevIDs). Keys are journal symbols, lowercase.

use serde::Deserialize;
use std::collections::HashMap;

#[derive(Debug, Deserialize)]
pub struct Catalog {
    pub source: String,
    pub ships: HashMap<String, ShipDef>,
    pub modules: HashMap<String, ModuleDef>,
}

/// A hull's base stats.
#[derive(Debug, Deserialize)]
pub struct ShipDef {
    pub name: String,
    pub hull_mass: f64,
    /// Top speed and boost speed at optimal mass with four pips to engines, m/s.
    pub speed: f64,
    pub boost: f64,
    /// Speed with no pips to engines, as a percentage of `speed`.
    pub minthrust: f64,
    /// Engine capacitor energy one boost takes, MJ.
    pub boost_energy: f64,
    pub base_shield: f64,
    pub base_armour: f64,
    pub hardness: f64,
    /// Fuel in the reservoir that feeds the power plant, t; it adds to the mass.
    #[serde(default)]
    pub reserve_fuel: f64,
}

/// A module's base stats, with coriolis-data's stat names (which engineering also uses).
#[derive(Debug, Deserialize)]
pub struct ModuleDef {
    /// Module group (`fsd`, `sg`, `mc`, `bh` for armour, ...).
    pub grp: String,
    pub class: u8,
    pub rating: String,
    pub stats: HashMap<String, f64>,
    /// Draws power while hardpoints are retracted (utility modules such as shield boosters).
    #[serde(default)]
    pub passive: bool,
}

pub fn catalog() -> &'static Catalog {
    static C: std::sync::OnceLock<Catalog> = std::sync::OnceLock::new();
    C.get_or_init(|| serde_json::from_str(include_str!("../../../data/catalog/ships.json")).expect("ships.json"))
}

pub fn ship(symbol: &str) -> Option<&'static ShipDef> {
    catalog().ships.get(&symbol.to_ascii_lowercase())
}

pub fn module(item: &str) -> Option<&'static ModuleDef> {
    catalog().modules.get(&item.to_ascii_lowercase())
}
